import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import vm from 'node:vm';import {validateBlueprintLibrary} from '../../reda-2/blueprint-validator.mjs';
test('curated clinical library exposes bidirectional progression graphs',()=>{const core={blueprints:{knee_pf:{},knee_oa:{},knee_tendon:{},shoulder_load:{},hip_gtps:{},achilles:{},neck:{},lumbar:{}}};const ctx={RedaClinical:core,RedaData:{exercises:[]}};vm.createContext(ctx);vm.runInContext(fs.readFileSync(new URL('../../reda-2/clinical-library-v3.js',import.meta.url),'utf8'),ctx);for(const id of ['knee_oa','knee_tendon','shoulder_load','achilles']){const g=core.blueprints[id].progressionGraph;assert.ok(g.nodes.length>=3);assert.ok(g.edges.some(e=>e.kind==='advance'));assert.ok(g.edges.some(e=>e.kind==='regress'))}});
test('validator rejects unknown exercise references',()=>{const v=validateBlueprintLibrary({x:{slots:['a'],progressionGraph:{start:'n',nodes:[{id:'n',exercises:{bad:{}}}],edges:[]}}},['a']);assert.equal(v.valid,false);assert.match(v.errors.join(' '),/bad/)});
